(async () => {
  const pages = figma.root.children;
  const result = {};

  for (const page of pages) {
    await figma.setCurrentPageAsync(page);
    const textNodes = page.findAll(n => n.type === 'TEXT');
    const pageTexts = textNodes.map(t => ({
      name: t.name,
      characters: t.characters,
      id: t.id
    }));

    const components = page.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET');
    const pageComponents = components.map(c => ({
      name: c.name,
      type: c.type,
      id: c.id
    }));

    result[page.name] = {
      id: page.id,
      textCount: textNodes.length,
      texts: pageTexts.slice(0, 50), // sample/first 50 texts
      components: pageComponents
    };
  }
  return result;
})()

(async () => {
  const page = figma.root.children.find(p => p.name.includes("00"));
  if (!page) return "Page 00 not found";
  await figma.setCurrentPageAsync(page);
  const textNodes = page.findAll(n => n.type === 'TEXT');
  return textNodes.map(t => ({
    name: t.name,
    characters: t.characters,
    id: t.id
  }));
})()

(async () => {
  const pages = figma.root.children;
  const compPage = pages.find(p => p.name.includes("02"));
  const mediaPage = pages.find(p => p.name.includes("04"));

  const getComponentsInfo = (page) => {
    if (!page) return null;
    const comps = page.findAll(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET');
    return comps.map(c => ({
      name: c.name,
      id: c.id,
      x: c.x,
      y: c.y,
      width: c.width,
      height: c.height,
      type: c.type
    }));
  };

  return {
    compPage: getComponentsInfo(compPage),
    mediaPage: getComponentsInfo(mediaPage)
  };
})()

(async () => {
  const ids = ["1:22", "1:25", "1:30", "1:40", "3:45", "2:20"];
  const results = {};
  for (const id of ids) {
    const node = figma.getNodeById(id);
    results[id] = node ? { name: node.name, type: node.type } : null;
  }
  return results;
})()

(async () => {
  const page = figma.root.children.find(p => p.name.includes("03"));
  if (!page) return "Workspace not found";
  await figma.setCurrentPageAsync(page);

  // Clear any existing children in 03 · Workspace to start fresh
  for (const child of page.children) {
    child.remove();
  }
  return "Workspace cleared";
})()

