  function findChildByName(parent, name) {
    if (parent.name === name) return parent;
    if ("children" in parent) {
      for (const child of parent.children) {
        const res = findChildByName(child, name);
        if (res) return res;
      }
    }
    return null;
  }

  const f1 = workspace.children.find(n => n.name === "01_Aktivitas");
  const f2 = workspace.children.find(n => n.name === "02_Trending");
  const f3 = workspace.children.find(n => n.name === "03_Detail_Saham");
  const f4 = workspace.children.find(n => n.name === "04_Top_Up_Metode");
  const f5 = workspace.children.find(n => n.name === "05_Top_Up_Nominal");
  const f6 = workspace.children.find(n => n.name === "06_Top_Up_Pembayaran");

  if (!f1 || !f2 || !f3 || !f4 || !f5 || !f6) {
    return `Missing frames: f1:${!!f1}, f2:${!!f2}, f3:${!!f3}, f4:${!!f4}, f5:${!!f5}, f6:${!!f6}`;
  }

  const reaction = {
    action: { type: "NODE", destinationId: null },
    trigger: { type: "ON_CLICK" }
  };

  // Helper to set reaction
  function wire(sourceNode, targetFrame) {
    if (!sourceNode || !targetFrame) return false;
    sourceNode.reactions = [{
      action: { type: "NODE", destinationId: targetFrame.id },
      trigger: { type: "ON_CLICK" }
    }];
    return true;
  }

  const results = [];

  // Frame 01_Aktivitas links:
  // Deposit -> 04_Top_Up_Metode
  // Trending tab -> 02_Trending
  // Top Up tab -> 04_Top_Up_Metode
  results.push("01 Deposit: " + wire(findChildByName(f1, "Button_Deposit"), f4));
  results.push("01 Trending tab: " + wire(findChildByName(f1, "Tab_Trending"), f2));
  results.push("01 Top Up tab: " + wire(findChildByName(f1, "Tab_Top Up"), f4));

  // Frame 02_Trending links:
  // GOTO -> 03_Detail_Saham
  // Aktivitas tab -> 01_Aktivitas
  // Top Up tab -> 04_Top_Up_Metode
  results.push("02 GOTO: " + wire(findChildByName(f2, "Row_GOTO"), f3));
  results.push("02 Aktivitas tab: " + wire(findChildByName(f2, "Tab_Aktivitas"), f1));
  results.push("02 Top Up tab: " + wire(findChildByName(f2, "Tab_Top Up"), f4));

  // Frame 03_Detail_Saham links:
  // back -> 02_Trending
  // Note: Icon_Back or Header back node
  const f3Back = findChildByName(f3, "Icon_Back") || findChildByName(f3, "Header")?.children?.[0];
  results.push("03 Back: " + wire(f3Back, f2));

  // Frame 04_Top_Up_Metode links:
  // Alfamart -> 05_Top_Up_Nominal
  // back -> 01_Aktivitas
  const f4Back = findChildByName(f4, "Icon_Back") || findChildByName(f4, "Header")?.children?.[0];
  results.push("04 Alfamart: " + wire(findChildByName(f4, "Method_Alfamart"), f5));
  results.push("04 Back: " + wire(f4Back, f1));

  // Frame 05_Top_Up_Nominal links:
  // Bayar -> 06_Top_Up_Pembayaran
  // back / Ganti -> 04_Top_Up_Metode
  const f5Back = findChildByName(f5, "Icon_Back") || findChildByName(f5, "Header")?.children?.[0];
  const f5Ganti = findChildByName(f5, "Method Card");
  results.push("05 Bayar: " + wire(findChildByName(f5, "Button_Bayar"), f6));
  results.push("05 Back: " + wire(f5Back, f4));
  if (f5Ganti) results.push("05 Ganti: " + wire(f5Ganti, f4));

  // Frame 06_Top_Up_Pembayaran links:
  // Oke -> 01_Aktivitas
  results.push("06 Oke: " + wire(findChildByName(f6, "Button_Oke"), f1));

  return results;
})()

